-- Pink Presentation
--
-- Pokemon Pink's sprites and pictures, built on the player's machine at
-- startup.  Pink drew them over the games' own art (its gym leaders are
-- Gold/Silver's sprites, touched up, and Sabrina is Yellow's Silph worker
-- redrawn; its Elite Four, Giovanni and 38 battle pictures are Yellow's,
-- edited), so this mod ships only the
-- pixels Pink changed (art_data.lua, generated by tools/gen_art_data.py)
-- and starts each picture from the player's own import.
--
-- The result is written to save/mod-derived/pink_presentation/, where the
-- engine uses a loaded mod's derived art in place of the imported picture.
-- Without a Gold, Silver or Crystal import the gym leaders keep Yellow's
-- sprites.
--
-- Needs engine_internals: src.import.CacheFs reads the other games'
-- imports, and the battle-picture matte is the importer's own.

return function(mod)
  local function own(path)
    local src = mod:read(path)
    if type(src) ~= "string" then error("can't read " .. path) end
    local chunk, err = load(src, "@pink_presentation/" .. path)
    if not chunk then error(err) end
    return chunk()
  end

  local A = own("art_data.lua")

  local okT, Transform = pcall(require, "src.mods.AssetTransform")
  local ROOT = okT and type(Transform) == "table" and Transform.SOURCE_ROOT
  if type(ROOT) ~= "string" then
    mod.log:warn("the engine's art root is unavailable; Pink's sprites are not built")
    return
  end

  -- Building needs images and a writable save folder; headless tools
  -- (modkit) have neither, so they only see the records below.
  local canBuild = love and love.image and love.filesystem and love.filesystem.write
  local okFs, CacheFs = pcall(require, "src.import.CacheFs")
  local okW, ImageWriter = pcall(require, "src.import.ImageWriter")
  if canBuild and not (okFs and type(CacheFs) == "table" and type(CacheFs.readAt) == "function") then
    mod.log:warn("CacheFs is unavailable; Pink's sprites are not built")
    canBuild = false
  end

  local GREY = { 0, 85 / 255, 170 / 255, 1 }

  local function decode(bytes, name)
    if type(bytes) ~= "string" then return nil end
    local ok, img = pcall(function()
      return love.image.newImageData(love.filesystem.newFileData(bytes, name))
    end)
    return ok and img or nil
  end

  local function readBase(base)
    local ok, bytes = pcall(CacheFs.readAt, base.game .. "/" .. ROOT .. base.rel)
    return ok and decode(bytes, base.game .. "/" .. base.rel) or nil
  end

  -- the importer's thresholds (PaletteFX 0.83 / 0.5 / 0.17); transparent is white
  local function shadeOf(r, a)
    if a == 0 or r > 0.83 then return 3 end
    if r > 0.5 then return 2 end
    if r > 0.17 then return 1 end
    return 0
  end

  local outRoot = "save/mod-derived/" .. mod.id .. "/"

  local function firstBase(bases)
    for _, b in ipairs(bases) do
      local img = readBase(b)
      if img then return img end
    end
  end

  -- a sheet put together frame by frame (16x16 frames in a vertical strip)
  local function composeFrames(job)
    local w, h = job.size[1], job.size[2]
    local out = love.image.newImageData(w, h)
    for _, f in ipairs(job.parts) do
      local src = firstBase(f.bases)
      if not src or src:getWidth() ~= w or src:getHeight() < (f.src + 1) * 16 then return nil end
      out:paste(src, 0, f.dst * 16, 0, f.src * 16, w, 16)
    end
    return out
  end

  local function build(job)
    local base
    if job.parts then
      base = composeFrames(job)
    else
      base = firstBase(job.bases)
    end
    if not base then return false, "no import has it" end
    local w, h = job.size[1], job.size[2]
    if base:getWidth() ~= w or base:getHeight() ~= h then
      return false, "the imported picture has another size"
    end
    local perm = job.perm
    local out = love.image.newImageData(w, h)
    for y = 0, h - 1 do
      for x = 0, w - 1 do
        local r, _, _, a = base:getPixel(x, y)
        local s = shadeOf(r, a)
        if perm then s = perm[s + 1] end
        local v = GREY[s + 1]
        out:setPixel(x, y, v, v, v, 1)
      end
    end
    local p = job.patch
    for i = 1, #p, 2 do
      local index, s = p[i], p[i + 1]
      local v = GREY[s + 1]
      out:setPixel(index % w, math.floor(index / w), v, v, v, 1)
    end
    if job.matte then
      if not (okW and type(ImageWriter) == "table" and ImageWriter.matteColor0) then
        return false, "the importer's matte is unavailable"
      end
      ImageWriter.matteColor0(out)
    end
    local path = outRoot .. job.out
    local dir = path:match("^(.*)/[^/]+$")
    if dir then love.filesystem.createDirectory(dir) end
    local png = out:encode("png"):getString()
    local existing = love.filesystem.getInfo(path) and love.filesystem.read(path)
    if existing ~= png then love.filesystem.write(path, png) end
    return true
  end

  -- a built sheet is there if this run made it or an earlier one did
  local function present(rel)
    return love and love.filesystem and love.filesystem.getInfo
      and love.filesystem.getInfo(outRoot .. rel) ~= nil
  end

  local built, failed = 0, 0
  local ready = {}
  for _, job in ipairs(A.jobs) do
    local ok, why = false, nil
    if canBuild then ok, why = build(job) end
    if ok or present(job.out) then
      built = built + 1
      ready[job.out] = true
    elseif canBuild then
      failed = failed + 1
      mod.log:info("%s kept the game's own art (%s)", job.out, tostring(why))
    end
  end
  if canBuild then
    mod.log:info("built %d pictures (%d kept the game's own)", built, failed)
  end

  -- Gym leaders get their own sprites (Pink's SPRITE_BROCK and friends).
  -- A sheet that couldn't be built (no Gen 2 import) leaves Yellow's sprite.
  local function setLeader(mapId, index, sprite)
    local map = mod.content.maps:get(mapId)
    if not (map and map.objects and map.objects[index]) then return end
    local objects = {}
    for i, o in ipairs(map.objects) do
      local copy = {}
      for k, v in pairs(o) do copy[k] = v end
      objects[i] = copy
    end
    objects[index].sprite = sprite
    mod.content.maps:patch(mapId, { objects = objects })
  end

  for _, job in ipairs(A.jobs) do
    if job.sprite and ready[job.out] then
      mod.content.sprites:override(job.sprite, {
        id = job.sprite,
        image = ROOT .. job.out,
        frames = job.frames,
        walker = job.walker,
      })
      setLeader(job.gym, job.object, job.sprite)
    end
  end
end
